import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import MapView from '../../components/MapView';

const DistanceReport = () => {
  const { user } = useAuth();
  const navigate = useNavigate();

  const [subjects, setSubjects] = useState([]);
  const [selectedSubjectId, setSelectedSubjectId] = useState('');
  const [sections, setSections] = useState([]);
  const [filteredSections, setFilteredSections] = useState([]);
  const [showOnlyNearby, setShowOnlyNearby] = useState(false);
  const [loading, setLoading] = useState(false);
  const [enrolling, setEnrolling] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Ubicación del estudiante desde la BD
  const [studentLocation, setStudentLocation] = useState(null);
  const [locationLoading, setLocationLoading] = useState(true);

  // Cargar ubicación del estudiante al montar
  useEffect(() => {
    const fetchStudentLocation = async () => {
      try {
        const res = await api.get(`/api/students/${user.id}/location`);
        setStudentLocation(res.data); // espera { lat, lng }
      } catch (err) {
        setError('No se pudo obtener tu ubicación registrada.');
      } finally {
        setLocationLoading(false);
      }
    };
    if (user?.id) {
      fetchStudentLocation();
    }
  }, [user]);

  // Cargar asignaturas disponibles al montar
  useEffect(() => {
    const fetchSubjects = async () => {
      try {
        const res = await api.get('/api/subjects');
        setSubjects(res.data);
        if (res.data.length > 0) {
          setSelectedSubjectId(res.data[0].id);
        }
      } catch (err) {
        setError('Error al cargar las asignaturas.');
      }
    };
    fetchSubjects();
  }, []);

  // Cuando cambia la asignatura y hay ubicación, buscar secciones cercanas
  useEffect(() => {
    if (selectedSubjectId && studentLocation) {
      fetchNearbySections(selectedSubjectId, studentLocation.lat, studentLocation.lng);
    }
  }, [selectedSubjectId, studentLocation]);

  const fetchNearbySections = async (subjectId, lat, lng) => {
    setLoading(true);
    setError('');
    try {
      const res = await api.get('/api/enrollments/nearby-sections', {
        params: { subjectId, lat, lng },
      });
      setSections(res.data);
      setFilteredSections(res.data);
    } catch (err) {
      setError('Error al cargar secciones cercanas.');
    } finally {
      setLoading(false);
    }
  };

  // Aplicar filtro de "solo cercanas" (≤ 150m)
  useEffect(() => {
    if (showOnlyNearby) {
      setFilteredSections(sections.filter(sec => sec.distanceMeters <= 150));
    } else {
      setFilteredSections(sections);
    }
  }, [showOnlyNearby, sections]);

  const handleSubjectChange = (e) => {
    setSelectedSubjectId(e.target.value);
    setSuccess('');
    setError('');
  };

  const handleToggle = () => setShowOnlyNearby(!showOnlyNearby);

  const handleEnroll = async (sectionId) => {
    if (!sectionId) {
      setError('Selecciona una sección para inscribirte.');
      return;
    }
    setEnrolling(true);
    setError('');
    setSuccess('');
    try {
      await api.post('/api/enrollments/enroll', {
        studentId: user.id,
        sectionId: sectionId,
      });
      setSuccess('¡Inscripción exitosa!');
      if (studentLocation) {
        fetchNearbySections(selectedSubjectId, studentLocation.lat, studentLocation.lng);
      }
    } catch (err) {
      const msg = err.response?.data?.message || 'Error al inscribirte.';
      setError(msg);
    } finally {
      setEnrolling(false);
    }
  };

  // Preparar puntos para el mapa
  const mapPoints = filteredSections
    .filter(sec => sec.geomGeoJson)
    .map(sec => ({
      id: sec.sectionId,
      name: sec.roomName,
      geomGeoJson: sec.geomGeoJson,
      popupText: `${sec.roomName} (${Math.round(sec.distanceMeters)}m)`,
    }));

  return (
    <div className="container py-4">
      <h2 className="fw-bold mb-3">Reporte de Distancias - Inscripción Inteligente</h2>
      <p className="text-muted">
        Basado en tu ubicación registrada, te mostraremos las secciones que están a menos de 300 metros.
      </p>

      {locationLoading && <div className="spinner-border text-primary" role="status"><span className="visually-hidden">Cargando ubicación...</span></div>}

      {!locationLoading && studentLocation && (
        <div className="mb-3">
          <span className="badge bg-success">
            📍 Tu ubicación registrada: {studentLocation.lat.toFixed(5)}, {studentLocation.lng.toFixed(5)}
          </span>
        </div>
      )}

      {!locationLoading && !studentLocation && (
        <div className="alert alert-warning">
          No tienes una ubicación registrada. Por favor, actualiza tu perfil con tu dirección.
        </div>
      )}

      {/* Selector de asignatura */}
      <div className="mb-3">
        <label className="form-label fw-semibold">Asignatura</label>
        <select
          className="form-select"
          value={selectedSubjectId}
          onChange={handleSubjectChange}
        >
          {subjects.map(sub => (
            <option key={sub.id} value={sub.id}>
              {sub.code} - {sub.name}
            </option>
          ))}
        </select>
      </div>

      {studentLocation && (
        <>
          <div className="form-check mb-3">
            <input
              className="form-check-input"
              type="checkbox"
              id="nearbyToggle"
              checked={showOnlyNearby}
              onChange={handleToggle}
            />
            <label className="form-check-label" htmlFor="nearbyToggle">
              Solo mostrar muy cercanas (≤ 150m)
            </label>
          </div>

          {loading && <div className="spinner-border text-primary" role="status"><span className="visually-hidden">Cargando...</span></div>}

          {!loading && filteredSections.length === 0 && (
            <div className="alert alert-info">
              {sections.length === 0
                ? 'No hay secciones disponibles dentro de 300m.'
                : 'No hay secciones a menos de 150m. Intenta desactivar el filtro.'}
            </div>
          )}

          {filteredSections.length > 0 && (
            <div className="list-group mb-3">
              {filteredSections.map((sec) => (
                <div
                  key={sec.sectionId}
                  className="list-group-item list-group-item-action d-flex justify-content-between align-items-center"
                >
                  <div>
                    <strong>{sec.roomName}</strong>
                    <span className="text-muted ms-2">({sec.buildingName})</span>
                    {sec.distanceMeters <= 150 && (
                      <span className="badge bg-success ms-2">⭐ A 150m de ti</span>
                    )}
                    <div className="small text-muted">
                      Código: {sec.sectionCode} · Distancia: {Math.round(sec.distanceMeters)} m
                    </div>
                  </div>
                  <button
                    className="btn btn-primary btn-sm"
                    onClick={() => handleEnroll(sec.sectionId)}
                    disabled={enrolling}
                  >
                    Inscribir
                  </button>
                </div>
              ))}
            </div>
          )}

          {error && <div className="alert alert-danger">{error}</div>}
          {success && <div className="alert alert-success">{success}</div>}

          {/* Mapa de las secciones cercanas */}
          {mapPoints.length > 0 && studentLocation && (
            <div className="mt-3" style={{ height: '300px' }}>
              <MapView
                center={[studentLocation.lat, studentLocation.lng]}
                zoom={17}
                pendingMarker={[studentLocation.lat, studentLocation.lng]}
                rooms={mapPoints}
              />
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default DistanceReport;
